def lps(s: str) -> int:
    def longest_palindromic_subsequence(s: str) -> int:
        n = len(s)
        dp = [[0] * n for _ in range(n)]

        # Base case: single character palindromes
        for i in range(n):
            dp[i][i] = 1

        # Fill the table for substrings of length 2 to n
        for length in range(2, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                if s[i] == s[j]:
                    dp[i][j] = dp[i + 1][j - 1] + 2
                else:
                    dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])

        return dp[0][n - 1]

    # Remove non-alphabetic characters, spaces, and convert to uppercase
    s = ''.join(filter(str.isalpha, s)).upper()
    return longest_palindromic_subsequence(s)

# Example usage:
assert lps("TENS FOR TENS") == 5
