def sum_of_digits(numbers):
    def sum_digits(num):
        # Sum the digits of a number
        return sum(int(digit) for digit in str(num) if digit.isdigit())

    # Flatten and filter the input list to handle nested lists and ensure valid elements
    flat_list = []
    for item in numbers:
        if isinstance(item, list):
            flat_list.extend(item)
        else:
            flat_list.append(item)

    # Compute the sum of digits for valid integers in the flattened list
    return sum(sum_digits(num) for num in flat_list if isinstance(num, int))

# Example usage and tests
assert sum_of_digits([10, 2, 56]) == 14
assert sum_of_digits([10, 20, 4, 5, 'b', 70, 'a']) == 19
assert sum_of_digits([100, 'hello', 25, 0, None]) == 8
assert sum_of_digits([]) == 0
assert sum_of_digits([1, 2, 3, 4, 5]) == 15
assert sum_of_digits([[10, 20, 4, 5, 'b', 70, 'a']]) == 19
